import{R as s,e as a,f as i,U as t}from"./chunks/framework.ywem4qy5.js";const u=JSON.parse('{"title":"Dropdown","description":"","frontmatter":{},"headers":[],"relativePath":"fields/dropdown.md","filePath":"fields/dropdown.md","lastUpdated":1778027571000}'),n={name:"fields/dropdown.md"};function o(l,e,r,d,p,h){return a(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="dropdown" tabindex="-1">Dropdown <a class="header-anchor" href="#dropdown" aria-label="Permalink to &quot;Dropdown&quot;">​</a></h1><p>Use Dropdown when someone should choose from a defined list and the options do not need to be visible all at once.</p><p>Use Dropdown for compact choice fields, especially when the list is long. If the choices are few and should stay visible, Radio or Checkboxes may be clearer.</p><h2 id="key-settings" tabindex="-1">Key settings <a class="header-anchor" href="#key-settings" aria-label="Permalink to &quot;Key settings&quot;">​</a></h2><ul><li><strong>Options</strong> - Define the available choices. Keep option values stable once submissions, exports or integrations depend on them.</li><li><strong>Multiple selections</strong> - Allow one selected value or a list of selected values.</li><li><strong>Default value</strong> - Preselect one or more options for new submissions.</li><li><strong>Placeholder</strong> - Show an initial prompt before a value is selected.</li><li><strong>Required</strong> - Force a choice before the form can be submitted.</li></ul><h2 id="bulk-add-options" tabindex="-1">Bulk Add Options <a class="header-anchor" href="#bulk-add-options" aria-label="Permalink to &quot;Bulk Add Options&quot;">​</a></h2><p>Use Bulk add options when you need to add a long list, such as countries, states, currencies or another repeated option set. You can start from Formie’s predefined options, choose which source field should be used for the label and value, then append those options to the field or replace the existing options.</p><p>You can also paste your own options into the bulk editor. Use one option per line:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Australia|AU</span></span>
<span class="line"><span>New Zealand|NZ</span></span>
<span class="line"><span>United States|US</span></span></code></pre></div><p>If you only provide one value on a line, Formie uses it for both the label and value.</p><h2 id="overriding-options" tabindex="-1">Overriding Options <a class="header-anchor" href="#overriding-options" aria-label="Permalink to &quot;Overriding Options&quot;">​</a></h2><p>If the options need to come from template logic, you can override the field’s <code>options</code> before rendering the form. See <a href="/templates/overriding-settings">Overriding Settings</a>.</p><h2 id="submitted-value" tabindex="-1">Submitted value <a class="header-anchor" href="#submitted-value" aria-label="Permalink to &quot;Submitted value&quot;">​</a></h2><p>Dropdown stores the selected option value. When multiple selections are enabled, it stores a list of selected option values.</p><p>When querying or saving submissions through GraphQL, the field handle is used as the field name. Query the form’s <code>formFields</code> and include <code>inputTypeName</code> if you need to confirm the generated input type for a specific form.</p><h2 id="theme-config" tabindex="-1">Theme config <a class="header-anchor" href="#theme-config" aria-label="Permalink to &quot;Theme config&quot;">​</a></h2><p>The Dropdown field can be targeted with the <code>dropdown</code> theme config key.</p><div class="language-twig vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">twig</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ craft.formie.renderForm(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;contactForm&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    themeConfig: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        dropdown: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            fieldInput: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                attributes: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                    class: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;my-dropdown-input&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}) }}</span></span></code></pre></div><p>Use theme config for class and attribute changes. Use a template override only when the <code>&lt;select&gt;</code> markup or option rendering needs to change.</p><p>For full Tailwind, Bootstrap and other framework examples, see <a href="https://github.com/verbb/formie-theme-configs" target="_blank" rel="noreferrer">Formie theme configs</a>.</p><h2 id="related-fields" tabindex="-1">Related fields <a class="header-anchor" href="#related-fields" aria-label="Permalink to &quot;Related fields&quot;">​</a></h2><ul><li>Use <a href="/fields/radio">Radio</a> when a short list should stay visible.</li><li>Use <a href="/fields/checkboxes">Checkboxes</a> when several choices can be selected and visibility matters more than compactness.</li></ul>`,22)])])}const f=s(n,[["render",o]]);export{u as __pageData,f as default};
